def solve(path: str) -> str:
    """Simplify an absolute Unix file path.
    Resolve '.' (current directory) and '..' (parent directory), collapse multiple slashes,
    and remove any trailing slash (except for root). The returned path always starts with '/'.
    """
    if not path:
        return '/'  # Edge case, treat empty as root
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            # Skip empty components caused by // or current directory
            continue
        if part == '..':
            if stack:
                stack.pop()
            # If stack empty, we stay at root, ignore further '..'
        else:
            stack.append(part)
    simplified = '/' + '/'.join(stack)
    return simplified if simplified != '' else '/'

