def solve(line):
    # Handle empty line
    if line == '':
        return ['']
    fields = []
    i = 0
    n = len(line)
    while i < n:
        if line[i] == '"':
            # quoted field
            i += 1
            field_chars = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i+1] == '"':
                        field_chars.append('"')
                        i += 2
                    else:
                        i += 1  # closing quote
                        break
                else:
                    field_chars.append(line[i])
                    i += 1
            # after closing quote, expect comma or end
            while i < n and line[i] != ',':
                # skip any extra characters (shouldn't be any per spec)
                i += 1
            fields.append(''.join(field_chars))
        else:
            # unquoted field
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])
        # skip comma
        if i < n and line[i] == ',':
            i += 1
    # trailing comma already handled by loop producing empty field because after comma i points to end, loop will exit without adding empty field. Need add if line ends with comma.
    if line and line[-1] == ',':
        fields.append('')
    return fields

