    """Return the number of prime numbers strictly less than n.
    Handles any integer n (including negative) by returning 0 for n <= 2.
    Uses a simple trial‑division check which avoids large memory usage.
    """
    if n <= 2:
        return 0
    def is_prime(x: int) -> bool:
        if x < 2:
            return False
        if x % 2 == 0:
            return x == 2
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    count = 0
    for i in range(2, n):
        if is_prime(i):
            count += 1
    return count

