def solve(meetings):
    """Return the maximum number of non‑overlapping meetings.
    meetings: iterable of [start, end] pairs (list, tuple, etc.).
    A meeting may start exactly when another ends.
    """
    # Convert to list of pairs for safe manipulation
    meetings = list(meetings)
    if not meetings:
        return 0
    # Ensure each meeting has two comparable items; ignore malformed entries
    valid = []
    for m in meetings:
        try:
            start, end = m[0], m[1]
        except Exception:
            continue
        # Coerce to numbers if possible, else skip
        try:
            start = float(start)
            end = float(end)
        except Exception:
            continue
        valid.append((start, end))
    # Sort by end time, then start time for deterministic ordering
    valid.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -float('inf')
    for start, end in valid:
        if start >= current_end:
            count += 1
            current_end = end
    return count

