def solve(a: str, b: str) -> int:
    """Compute Levenshtein edit distance between strings a and b.
    Operations: insert, delete, replace (cost 1 each).
    """
    m, n = len(a), len(b)
    # If one string is empty
    if m == 0:
        return n
    if n == 0:
        return m
    # DP table rows for a (0..m) and columns for b (0..n)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                cost = 0
            else:
                cost = 1
            dp[i][j] = min(
                dp[i - 1][j] + 1,      # deletion
                dp[i][j - 1] + 1,      # insertion
                dp[i - 1][j - 1] + cost  # substitution
            )
    return dp[m][n]

