import heapq

def solve(n, edges):
    # Shortest path from node 0 to node n-1 over undirected weighted edges [u, v, w]; -1 if unreachable.
    if n == 1:
        return 0
    adj = {}
    for u, v, w in edges:
        adj.setdefault(u, []).append((v, w))
        adj.setdefault(v, []).append((u, w))
    dist = {0: 0}
    heap = [(0, 0)]
    done = set()
    while heap:
        d, node = heapq.heappop(heap)
        if node in done:
            continue
        done.add(node)
        if node == n - 1:
            return d
        for nxt, w in adj.get(node, ()):
            nd = d + w
            if nd < dist.get(nxt, float('inf')):
                dist[nxt] = nd
                heapq.heappush(heap, (nd, nxt))
    return -1

